const clamp=(v,a,b,d=0)=>Number.isFinite(Number(v))?Math.min(b,Math.max(a,Number(v))):d;
export function normalizeAudioEdit(value={},duration=180){const track=(v={},music=false)=>({start:clamp(v.start,0,duration),end:v.end==null?null:clamp(v.end,0,duration),volume:clamp(v.volume,0,2,1),points:(Array.isArray(v.points)?v.points:[]).slice(0,100).map(p=>({time:clamp(p.time,0,duration),value:clamp(p.value,0,2,1)})).sort((a,b)=>a.time-b.time).filter((p,i,a)=>!i||p.time>a[i-1].time),...(music?{sourceStart:clamp(v.sourceStart,0,86400),sourceEnd:v.sourceEnd==null?null:clamp(v.sourceEnd,0,86400),offset:clamp(v.offset,0,duration),repeat:v.repeat!==false}:{})});return {original:track(value.original),music:track(value.music,true)};}
export function gainAt(track={},time=0){if(time<(track.start||0)||(track.end!=null&&time>=track.end))return 0;const points=track.points||[];let previous={time:0,value:track.volume??1};for(const p of points){if(p.time>time){const t=(time-previous.time)/Math.max(.001,p.time-previous.time);return previous.value+(p.value-previous.value)*Math.max(0,t)}previous=p;}return previous.value;}
export function musicSegments(track={},sourceDuration,total){const a=clamp(track.sourceStart,0,sourceDuration),b=track.sourceEnd==null?sourceDuration:clamp(track.sourceEnd,a,sourceDuration),length=b-a,offset=clamp(track.offset,0,total),parts=[];if(length<.05)return parts;for(let at=offset;at<total-.001;at+=length){parts.push({sourceStart:a,sourceEnd:a+Math.min(length,total-at),destStart:at});if(track.repeat===false)break;}return parts;}
export function musicPosition(track,sourceDuration,total,time){const parts=musicSegments(track,sourceDuration,total),p=parts.find(p=>time>=p.destStart&&time<p.destStart+p.sourceEnd-p.sourceStart);return p?p.sourceStart+time-p.destStart:null;}
export function mixSamples(input,sampleRate,projectStart,speed,track,base=1){const out=new Float32Array(input.length);for(let i=0;i<input.length;i++)out[i]=input[i]*base*gainAt(track,projectStart+i/sampleRate/speed);return out;}

export function audioEditForState(state,duration=180){return normalizeAudioEdit({...state.audioEdit,music:{volume:state.musicVolume??.25,...state.audioEdit?.music}},duration)}
